68	        this.unsentRequests = new ArrayDeque<>();
69	        this.requestTimeoutMs = config.getInt(ConsumerConfig.REQUEST_TIMEOUT_MS_CONFIG);
70	        this.retryBackoffMs = config.getLong(ConsumerConfig.RETRY_BACKOFF_MS_CONFIG);
71	        this.tryConnectNodes = new HashSet<>();
72	    }
