82	     * @param timeoutMs     timeout time
83	     * @param currentTimeMs current time
84	     * @return a list of client response
85	     */
86	    public void poll(final long timeoutMs, final long currentTimeMs) {
87	        trySend(currentTimeMs);
88	
89	        long pollTimeoutMs = timeoutMs;
90	        if (!unsentRequests.isEmpty()) {
91	            pollTimeoutMs = Math.min(retryBackoffMs, pollTimeoutMs);
92	        }
93	        this.client.poll(pollTimeoutMs, currentTimeMs);
94	        checkDisconnects(currentTimeMs);
95	    }
