97	    /**
98	     * Tries to send the requests in the unsentRequest queue. If the request doesn't have an assigned node, it will
99	     * find the leastLoadedOne, and will be retried in the next {@code poll()}. If the request is expired, a
100	     * {@link TimeoutException} will be thrown.
101	     */
102	    private void trySend(final long currentTimeMs) {
103	        Iterator<UnsentRequest> iterator = unsentRequests.iterator();
104	        while (iterator.hasNext()) {
105	            UnsentRequest unsent = iterator.next();
106	            unsent.timer.update(currentTimeMs);
107	            if (unsent.timer.isExpired()) {
108	                iterator.remove();
109	                unsent.handler.onFailure(currentTimeMs, new TimeoutException(
110	                    "Failed to send request after " + unsent.timer.timeoutMs() + " ms."));
111	                continue;
112	            }
113	
114	            if (!doSend(unsent, currentTimeMs)) {
115	                // continue to retry until timeout.
116	                continue;
117	            }
118	            iterator.remove();
119	        }
120	    }
121	
122	    private boolean doSend(final UnsentRequest r,
123	                           final long currentTimeMs) {
124	        Node node = r.node.orElse(client.leastLoadedNode(currentTimeMs));
125	        if (node == null || nodeUnavailable(node)) {
126	            log.debug("No broker available to send the request: {}. Retrying.", r);
127	            return false;
128	        }
129	        ClientRequest request = makeClientRequest(r, node, currentTimeMs);
130	        if (!client.ready(node, currentTimeMs)) {
131	            // enqueue the request again if the node isn't ready yet. The request will be handled in the next iteration
132	            // of the event loop
133	            log.debug("Node is not ready, handle the request in the next event loop: node={}, request={}", node, r);
134	            return false;
135	        }
136	        client.send(request, currentTimeMs);
137	        return true;
138	    }
