140	    private void checkDisconnects(final long currentTimeMs) {
141	        // Check the connection of the unsent request. Disconnect the disconnected node if it is unable to be connected.
142	        Iterator<UnsentRequest> iter = unsentRequests.iterator();
143	        while (iter.hasNext()) {
144	            UnsentRequest u = iter.next();
145	            if (u.node.isPresent() && client.connectionFailed(u.node.get())) {
146	                iter.remove();
147	                AuthenticationException authenticationException = client.authenticationException(u.node.get());
148	                u.handler.onFailure(currentTimeMs, authenticationException);
