181	    /**
182	     * Check if the code is disconnected and unavailable for immediate reconnection (i.e. if it is in reconnect
183	     * backoff window following the disconnect).
184	     */
185	    public boolean nodeUnavailable(final Node node) {
186	        return client.connectionFailed(node) && client.connectionDelay(node, time.milliseconds()) > 0;
187	    }
