191	     * @return ConsumerRecord.  It can be empty if time timeout expires.
192	     */
193	    @Override
194	    public ConsumerRecords<K, V> poll(final Duration timeout) {
195	        Timer timer = time.timer(timeout);
196	        try {
197	            do {
198	                if (!eventHandler.isEmpty()) {
199	                    final Optional<BackgroundEvent> backgroundEvent = eventHandler.poll();
200	                    // processEvent() may process 3 types of event:
201	                    // 1. Errors
202	                    // 2. Callback Invocation
203	                    // 3. Fetch responses
204	                    // Errors will be handled or rethrown.
205	                    // Callback invocation will trigger callback function execution, which is blocking until completion.
206	                    // Successful fetch responses will be added to the completedFetches in the fetcher, which will then
207	                    // be processed in the collectFetches().
208	                    backgroundEvent.ifPresent(event -> processEvent(event, timeout));
209	                }
210	
211	                updateFetchPositionsIfNeeded(timer);
212	
213	                // The idea here is to have the background thread sending fetches autonomously, and the fetcher
214	                // uses the poll loop to retrieve successful fetchResponse and process them on the polling thread.
215	                final Fetch<K, V> fetch = collectFetches();
216	                if (!fetch.isEmpty()) {
217	                    return processFetchResults(fetch);
218	                }
219	                // We will wait for retryBackoffMs
220	            } while (time.timer(timeout).notExpired());
221	        } catch (final Exception e) {
222	            throw new RuntimeException(e);
223	        }
224	        // TODO: Once we implement poll(), clear wakeupTrigger in a finally block: wakeupTrigger.clearActiveTask();
225	
226	        return ConsumerRecords.empty();
