239	        // Validate positions using the partition leader end offsets, to detect if any partition
240	        // has been truncated due to a leader change. This will trigger an OffsetForLeaderEpoch
241	        // request, retrieve the partition end offsets, and validate the current position against it.
242	        ValidatePositionsApplicationEvent validatePositionsEvent = new ValidatePositionsApplicationEvent();
