254	        // If there are partitions still needing a position and a reset policy is defined,
255	        // request reset using the default policy. If no reset strategy is defined and there
256	        // are partitions with a missing position, then we will raise a NoOffsetForPartitionException exception.
257	        subscriptions.resetInitializingPositions();
258	
259	        // Reset positions using partition offsets retrieved from the leader, for any partitions
260	        // which are awaiting reset. This will trigger a ListOffset request, retrieve the
261	        // partition offsets according to the strategy (ex. earliest, latest), and update the
262	        // positions.
263	        ResetPositionsApplicationEvent resetPositionsEvent = new ResetPositionsApplicationEvent();
264	        eventHandler.add(resetPositionsEvent);
