25	import java.util.Collection;
26	import java.util.HashSet;
27	import java.util.Set;
28	import java.util.concurrent.ConcurrentLinkedQueue;
29	import java.util.function.Predicate;
30	
31	/**
32	 * {@code FetchBuffer} buffers up {@link CompletedFetch the results} from the broker responses as they are received.
33	 * It is essentially a wrapper around a {@link java.util.Queue} of {@link CompletedFetch}. There is at most one
34	 * {@link CompletedFetch} per partition in the queue.
35	 *
36	 * <p/>
37	 *
38	 * <em>Note</em>: this class is not thread-safe and is intended to only be used from a single thread.
39	 */
40	public class FetchBuffer implements Closeable {
41	
42	    private final Logger log;
43	    private final ConcurrentLinkedQueue<CompletedFetch> completedFetches;
44	    private final IdempotentCloser idempotentCloser = new IdempotentCloser();
45	
46	    private CompletedFetch nextInLineFetch;
47	
48	    public FetchBuffer(final LogContext logContext) {
49	        this.log = logContext.logger(FetchBuffer.class);
50	        this.completedFetches = new ConcurrentLinkedQueue<>();
51	    }
52	
53	    /**
54	     * Returns {@code true} if there are no completed fetches pending to return to the user.
55	     *
56	     * @return {@code true} if the buffer is empty, {@code false} otherwise
57	     */
58	    boolean isEmpty() {
59	        return completedFetches.isEmpty();
60	    }
61	
62	    /**
63	     * Return whether we have any completed fetches pending return to the user. This method is thread-safe. Has
64	     * visibility for testing.
65	     *
66	     * @return {@code true} if there are completed fetches that match the {@link Predicate}, {@code false} otherwise
67	     */
68	    boolean hasCompletedFetches(Predicate<CompletedFetch> predicate) {
69	        return completedFetches.stream().anyMatch(predicate);
70	    }
71	
72	    void add(CompletedFetch completedFetch) {
73	        completedFetches.add(completedFetch);
74	    }
75	
76	    void addAll(Collection<CompletedFetch> completedFetches) {
77	        this.completedFetches.addAll(completedFetches);
78	    }
79	
80	    CompletedFetch nextInLineFetch() {
81	        return nextInLineFetch;
82	    }
83	
84	    void setNextInLineFetch(CompletedFetch completedFetch) {
85	        this.nextInLineFetch = completedFetch;
86	    }
87	
88	    CompletedFetch peek() {
89	        return completedFetches.peek();
90	    }
91	
92	    CompletedFetch poll() {
93	        return completedFetches.poll();
94	    }
95	
96	    /**
97	     * Updates the buffer to retain only the fetch data that corresponds to the given partitions. Any previously
98	     * {@link CompletedFetch fetched data} is removed if its partition is not in the given set of partitions.
99	     *
100	     * @param partitions {@link Set} of {@link TopicPartition}s for which any buffered data should be kept
101	     */
102	    void retainAll(final Set<TopicPartition> partitions) {
103	        completedFetches.removeIf(cf -> maybeDrain(partitions, cf));
104	
105	        if (maybeDrain(partitions, nextInLineFetch))
106	            nextInLineFetch = null;
107	    }
108	
109	    private boolean maybeDrain(final Set<TopicPartition> partitions, final CompletedFetch completedFetch) {
110	        if (completedFetch != null && !partitions.contains(completedFetch.partition)) {
111	            log.debug("Removing {} from buffered fetch data as it is not in the set of partitions to retain ({})", completedFetch.partition, partitions);
112	            completedFetch.drain();
113	            return true;
114	        } else {
115	            return false;
116	        }
117	    }
118	
119	    /**
120	     * Return the set of {@link TopicPartition partitions} for which we have data in the buffer.
121	     *
122	     * @return {@link TopicPartition Partition} set
123	     */
124	    Set<TopicPartition> bufferedPartitions() {
125	        final Set<TopicPartition> partitions = new HashSet<>();
126	
127	        if (nextInLineFetch != null && !nextInLineFetch.isConsumed()) {
128	            partitions.add(nextInLineFetch.partition);
129	        }
130	
131	        completedFetches.forEach(cf -> partitions.add(cf.partition));
132	        return partitions;
133	    }
134	
135	    @Override
136	    public void close() {
137	        idempotentCloser.close(() -> {
138	            log.debug("Closing the fetch buffer");
139	
140	            if (nextInLineFetch != null) {
141	                nextInLineFetch.drain();
142	                nextInLineFetch = null;
143	            }
144	
145	            completedFetches.forEach(CompletedFetch::drain);
146	            completedFetches.clear();
147	        }, () -> log.warn("The fetch buffer was previously closed"));
148	    }
149	}
