        this.log = logContext.logger(this.getClass());
        this.nonRetriableErrorHandler = errorHandler;
        this.groupId = groupId;
        this.coordinatorRequestState = new RequestState(
                logContext,
                CoordinatorRequestManager.class.getSimpleName(),
                retryBackoffMs,
                retryBackoffMaxMs
