19	import java.util.concurrent.atomic.AtomicBoolean;
20	import java.util.function.Supplier;
21	
22	/**
23	 * {@code IdempotentCloser} encapsulates some basic logic to ensure that a given resource is only closed once.
24	 * The underlying mechanism for ensuring that the close only happens once <em>and</em> is thread safe
25	 * is via the {@link AtomicBoolean#compareAndSet(boolean, boolean)}. Users can provide callbacks (via optional
26	 * {@link Runnable}s) for either the <em>initial</em> close and/or any <em>subsequent</em> closes.
27	 *
28	 * <p/>
29	 *
30	 * Here's an example:
31	 *
32	 * <pre>
33	 *
34	 * public class MyDataFile implements Closeable {
35	 *
36	 *     private final IdempotentCloser closer = new IdempotentCloser();
37	 *
38	 *     private final File file;
39	 *
40	 *     . . .
41	 *
42	 *     public boolean write() {
43	 *         closer.assertOpen(() -> String.format("Data file %s already closed!", file));
44	 *         writeToFile();
45	 *     }
46	 *
47	 *     public boolean isClosed() {
48	 *         return closer.isClosed();
49	 *     }
50	 *
51	 *     &#064;Override
52	 *     public void close() {
53	 *         Runnable onInitialClose = () -> {
54	 *             cleanUpFile(file);
55	 *             log.debug("Data file {} closed", file);
56	 *         };
57	 *         Runnable onSubsequentClose = () -> {
58	 *             log.warn("Data file {} already closed!", file);
59	 *         };
60	 *         closer.close(onInitialClose, onSubsequentClose);
61	 *     }
62	 * }
63	 * </pre>
64	 */
65	public class IdempotentCloser implements AutoCloseable {
66	
67	    private final AtomicBoolean isClosed;
68	
69	    /**
70	     * Creates an {@code IdempotentCloser} that is not yet closed.
71	     */
72	    public IdempotentCloser() {
73	        this(false);
74	    }
75	
76	    /**
