 * provided separately (see {@link Deserializers}) to the classes that deserialize the records, such as
 * {@link FetchCollector}, and are closed by their creator.
 */
public class FetchConfig {

    final int minBytes;
    final int maxBytes;
    final int maxWaitMs;
    final int fetchSize;
    final int maxPollRecords;
    final boolean checkCrcs;
    final String clientRackId;
    final IsolationLevel isolationLevel;

